<template>
  <div>
    <b-row>
      <b-col lg="11" md="8" sm="10">
        <b-row>
          <b-col cols="8"
            ><b>Contas cadastradas: {{ accounts.length }}</b></b-col
          >
          <b-col>
            <b-button
              size="sm"
              block
              variant="secondary"
              :disabled="isLoading"
              @click="generateAccountNumber()"
            >
              <b-icon icon="credit-card-fill"></b-icon> Gerar nova
              conta</b-button
            >
          </b-col>
          <b-col lg="1">
            <b-button
              size="sm"
              block
              variant="secondary"
              :disabled="isLoading"
              @click="getAllAccounts()"
            >
              <b-icon icon="arrow-clockwise"></b-icon
            ></b-button>
          </b-col>
        </b-row>
        <b-overlay :show="isLoading" rounded="sm">
          <p class="text-danger" v-if="accounts.length == 0">
            <b>Sem nenhuma conta cadastrada até o momento.</b>
          </p>
          <table v-else class="table table-sm table-hover table-stripped">
            <thead>
              <tr style="font-size: 9pt" class="bg-secondary text-white">
                <th>Número da conta</th>
                <th>Nome do cliente</th>
                <th>Data de cadastro</th>
                <th>Última actualização</th>
                <th class="text-center">Configs</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="account in accounts"
                :key="account.id"
                style="font-size: 9pt; cursor: pointer"
              >
                <td>{{ account.accountNumber }}</td>
                <td>{{ getAllocatedCustomer(account.accountNumber) }}</td>
                <td v-date-format="account.createdAt"></td>
                <td v-date-format="account.updatedAt"></td>
                <td>
                  <b-row v-if="account.customerId === null">
                    <b-col class="text-center" @click="deleteAccount(account)"
                      ><b-icon icon="trash-fill" variant="danger"></b-icon
                    ></b-col>
                    <b-col
                      class="text-center"
                      @click="updateAccount(account.accountNumber)"
                      >Associar
                      <b-icon
                        icon="person-plus-fill"
                        variant="secondary"
                      ></b-icon
                    ></b-col>
                  </b-row>
                  <b-row v-else>
                    <b-col
                      class="text-center text-primary"
                      @click="go2CustomerPanel(account.accountNumber)"
                    >
                      <b>Ir ao painel </b>
                      <b-icon
                        icon="eye-fill"
                        variant="primary"
                        font-scale="1"
                      ></b-icon
                    ></b-col>
                  </b-row>
                </td>
              </tr>
            </tbody>
          </table>
        </b-overlay>
      </b-col>
      <b-col> </b-col>
    </b-row>
    <b-modal hide-footer ref="delete-account" title="Deletar">
      <p class="text-danger text-center">
        Deseja realmente excluir esta conta?
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block size="sm" variant="danger" @click="decidedToDelete()"
            >Deletar</b-button
          >
        </b-col>
      </b-row>
    </b-modal>

    <b-modal hide-footer ref="open-account" title="Abrir uma conta">
      <h1 class="text-secondary" style="font-size: 12pt">
        <b>Número de conta</b>: {{ form.accountNumber }}
      </h1>
      <b-form-group label="Seleccione o cliente:" label-for="input-5">
        <b-form-select
          v-model="form.customerId"
          size="sm"
          :options="filteredCustomers"
          required
        ></b-form-select>
      </b-form-group>
      <b-row>
        <b-col>
          <b-button block size="sm" variant="primary" @click="cancelAction()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button
            block
            size="sm"
            variant="secondary"
            :disabled="isLoading"
            @click="associateAccount2Customer()"
            >Associar mutuário</b-button
          >
        </b-col>
      </b-row>
    </b-modal>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import logs from "../../utils/logs";

export default {
  name: "AccountsComponent",

  data: () => ({
    form: {
      createdBy: "",
      allocatedBy: "",
      customerId: 0,
      accountNumber: 0,
    },
    accountDeletionId: 0,
    filteredCustomers: [],
    accountSelected: {},
  }),

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "company",
      "accounts",
      "customers",
    ]),
  },

  created() {
    this.form.createdBy = this.user.name;
    this.form.allocatedBy = this.user.name;
    this.getAllAccounts();
    this.filterCustomers();
  },

  methods: {
    getAllAccounts() {
      this.$store.dispatch("getAllAccounts", this.company.id);
    },

    associateAccount2Customer() {
      if (this.form.customerId == 0) {
        this.showToast(
          "Aviso!",
          "warning",
          "Por favor, seleccione um cliente para associar a uma conta."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        axios
          .put(`/api/account/${this.form.accountNumber}`, this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast("Sucesso!", "success", data.message);
              this.$store.dispatch("getAllCustomers");
            } else {
              this.showToast("Erro!", "danger", data.message);
            }
            this.$store.commit("LOADING_STATUS", false);
            this.cancelAction();
          })
          .catch((err) => {
            this.$store.commit("LOADING_STATUS", false);
            this.showToast("Erro!", "danger", err.message);
            this.cancelAction();
          });
      }
    },

    filterCustomers() {
      const nonAllocatedCustomers = this.customers.filter((a) => {
        return a.accountNumber === null;
      });

      nonAllocatedCustomers.forEach((customer) => {
        let _customer = { text: customer.customerName, value: customer.id };
        this.filteredCustomers.push(_customer);
      });

      this.form.customerId =
        nonAllocatedCustomers.length > 0 ? nonAllocatedCustomers[0].id : 0;
    },

    updateAccount(accountNumber) {
      this.form.accountNumber = accountNumber;
      this.$refs["open-account"].show();
    },

    go2CustomerPanel(accountNumber) {
      const customer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      if (customer.length == 1) {
        this.showToast("Sucesso!", "success", customer[0].customerName);
        this.$store.commit("SET_CURRENT_CUSTOMER", customer[0]);
        this.$router.replace("/customer");
      } else {
        this.showToast(
          "Não foi possível abrir o painél",
          "warning",
          "Volte tentar mais tarde"
        );
      }
    },

    cancelAction() {
      this.form.accountNumber = 0;
      this.$refs["open-account"].hide();
    },

    getAllocatedCustomer(accountNumber) {
      const filteredCustomer = this.customers.filter((a) => {
        return a.accountNumber == accountNumber;
      });
      return filteredCustomer.length > 0
        ? filteredCustomer[0].customerName
        : "Mutuário não associado.";
    },

    generateAccountNumber() {
      if (this.form.createdBy.length < 4) {
        this.showToast(
          "Aviso!",
          "warning",
          "Houve um erro, volte a tentar mais tarde."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        this.form.companyId = this.company.id;
        axios
          .post("/api/account", this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast("Sucesso!", "success", data.message);
              const logsParams = logs(
                this.user,
                `${
                  parseInt(this.accounts[0].accountNumber) + 1
                } criada com sucesso.`,
                "Geração de conta"
              );
              this.$store.dispatch("addLog", logsParams);
              this.getAllAccounts();
            } else {
              this.showToast("Erro!", "danger", data.message);
            }
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.$store.commit("LOADING_STATUS", false);
            this.showToast("Erro!", "danger", err.message);
          });
      }
    },

    resetFields() {
      this.accountDeletionId = 0;
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/account/${this.accountDeletionId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${this.accountSelected.accountNumber} excluída com sucesso.`,
              "Exclusão de conta"
            );
            this.$store.dispatch("addLog", logsParams);
            this.getAllAccounts();
          } else {
            this.showToast("Erro!", "warning", data.message);
          }
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
          this.showToast("Erro!", "danger", err.message);
        });
    },

    deleteAccount(account) {
      this.accountDeletionId = account.id;
      this.accountSelected = account;
      this.$refs["delete-account"].show();
    },

    cancelDeletion() {
      this.accountDeletionId = 0;
      this.$refs["delete-account"].hide();
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>
