<template>
  <div>
    <b-row>
      <b-col lg="9" md="8" sm="10">
        <b-row>
          <b-col cols="11"
            ><b>Usuários cadastrados: {{ users.length }}</b></b-col
          >
          <b-col>
            <b-button
              size="sm"
              block
              variant="secondary"
              :disabled="isLoading"
              @click="refreshUsers()"
            >
              <b-icon icon="arrow-clockwise"></b-icon
            ></b-button>
          </b-col>
        </b-row>
        <b-overlay :show="isLoading" rounded="sm">
          <p class="text-danger" v-if="users.length == 0">
            Sem nenhum usuário cadastrado até o momento.
          </p>
          <table v-else class="table table-sm table-hover table-stripped">
            <thead>
              <tr style="font-size: 9pt" class="bg-secondary text-white">
                <th>Nome completo</th>
                <th>Telemóvel</th>
                <th>E-mail</th>
                <th>Perfil</th>
                <th>Data de cadastro</th>
                <th>Status</th>
                <th>Configs</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="user in users"
                :key="user.id"
                style="font-size: 9pt; cursor: pointer"
                :class="{
                  'text-danger': user.status === 0,
                  'bg-warning': userUpdationId === user.id,
                }"
              >
                <td>{{ user.name }}</td>
                <td>{{ user.phone }}</td>
                <td>{{ user.email }}</td>
                <td>{{ convertRole(user.userRole) }}</td>
                <td v-date-format="user.createdAt"></td>
                <td>{{ convertStatus(user.status) }}</td>
                <td>
                  <b-row style="font-size: 1rem">
                    <b-col class="text-center" @click="deleteUser(user)"
                      ><b-icon icon="trash-fill" variant="danger"></b-icon
                    ></b-col>
                    <b-col class="text-center" @click="updateUser(user)"
                      ><b-icon icon="pen-fill" variant="primary"></b-icon
                    ></b-col>
                    <b-col class="text-center" @click="decidedToReset(user)"
                      ><b-icon icon="unlock-fill" variant="danger"></b-icon>
                    </b-col>
                  </b-row>
                </td>
              </tr>
            </tbody>
          </table>
        </b-overlay>
      </b-col>
      <b-col>
        <h5>
          <b
            ><b-icon
              icon="person-plus-fill"
              variant="secondary"
              font-scale="1"
            ></b-icon
            >&nbsp;&nbsp;<small><b>Novo usuário</b></small></b
          >
        </h5>
        <hr class="bg-secondary mt-0" />
        <b-form-group label="Nome completo" class="mt-0" label-for="input-1">
          <b-form-input
            v-model="form.name"
            size="sm"
            type="text"
            placeholder="Nome completo"
            required
          ></b-form-input>
        </b-form-group>

        <b-form-group label="Telemóvel" label-for="input-2">
          <b-form-input
            v-model="form.phone"
            size="sm"
            placeholder="Digite o telemóvel"
            required
          ></b-form-input>
        </b-form-group>

        <b-form-group label="E-mail" label-for="input-3">
          <b-form-input
            v-model="form.email"
            type="email"
            size="sm"
            placeholder="Digite o email"
            required
          ></b-form-input>
        </b-form-group>

        <b-form-group
          :label="'Senha: ' + form.password"
          label-for="input-6"
          v-if="userUpdationId == 0"
        >
        </b-form-group>

        <b-form-group label="Perfil:" label-for="input-4">
          <b-form-select
            v-model="form.userRole"
            size="sm"
            :options="roles"
            required
          ></b-form-select>
        </b-form-group>

        <b-form-group label="Status:" label-for="input-5">
          <b-form-select
            v-model="form.status"
            size="sm"
            :options="userStatus"
            required
          ></b-form-select>
        </b-form-group>

        <b-row>
          <b-col lg="12" md="12" sm="12" class="d-flex align-items-center">
            <b-button
              :disabled="isLoading"
              type="submit"
              size="sm"
              block
              variant="success"
              v-if="userUpdationId == 0"
              @click="registerUser()"
              >Cadastrar usuário &nbsp;<b-icon icon="telegram"></b-icon
            ></b-button>
            <b-button
              :disabled="isLoading"
              type="submit"
              size="sm"
              block
              variant="success"
              v-else
              @click="updateConfirmation()"
              >Actualizar dados&nbsp;<b-icon icon="telegram"></b-icon
            ></b-button>
          </b-col>
        </b-row>
      </b-col>
    </b-row>
    <b-modal hide-footer ref="delete-user" title="Deletar">
      <p class="text-danger text-center">
        Deseja realmente excluir este usuário?
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeletion()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button block size="sm" variant="danger" @click="decidedToDelete()"
            >Deletar</b-button
          >
        </b-col>
      </b-row>
    </b-modal>

    <b-modal hide-footer ref="reset-user" title="Redefinir senha">
      <p class="text-danger text-center">
        Deseja realmente redefinir a senha de {{ selectedUserUpdate.name }}?
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelReset()">Cancelar</b-button>
        </b-col>
        <b-col>
          <b-button
            block
            size="sm"
            variant="success"
            @click="updateUserPassword()"
            >Redefinir</b-button
          >
        </b-col>
      </b-row>
    </b-modal>
  </div>
</template>

<script>
import axios from "axios";
import { mapGetters } from "vuex";
import logs from "@/utils/logs";

export default {
  name: "UserComponent",

  data: () => ({
    form: {
      name: "",
      phone: "258",
      email: "",
      password: Math.floor(Math.random() * 1000000) + 1,
      userRole: 3,
      status: 1,
      companyId: "",
    },
    roles: [
      { text: "Atendimento", value: 2 },
      { text: "Analista de crédito", value: 3 },
      { text: "Admin", value: 1 },
    ],
    userStatus: [
      { text: "Activo", value: 1 },
      { text: "Inactivo", value: 0 },
    ],
    userDeletionId: 0,
    selectedUser: {},
    selectedUserUpdate: {},
    userUpdationId: 0,
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "token", "company", "users"]),
  },

  methods: {
    refreshUsers() {
      this.$store.dispatch("getAllUsers", this.company.id);
    },

    decidedToReset(user) {
      this.$refs["reset-user"].show();
      this.selectedUserUpdate = user;
    },

    updateUserPassword() {
      const passingValues = {
        updatedPassword: 0,
      };
      this.$store.commit("LOADING_STATUS", true);

      axios
        .put(`/api/users/${this.selectedUserUpdate.id}`, passingValues)
        .then((res) => {
          const { success, message } = res.data;
          if (success === true) {
            console.log(res.data);
            this.showToast("Senha redefinida com sucesso!", "success", message);
            this.$store.commit("LOADING_STATUS", false);

            const logsParams = logs(
              this.user,
              `A senha do usuario: ${this.selectedUserUpdate.name} foi actualizada com sucesso.`,
              "Actualização de senha"
            );
            this.$store.dispatch("addLog", logsParams);
          } else {
            this.showToast("Erro!", "danger", message);
            this.$store.commit("LOADING_STATUS", false);
          }
          this.$refs["reset-user"].hide();
        })
        .catch((err) => {
          console.log(err);
          this.showToast("Erro!", "danger", err.message);
          this.$store.commit("LOADING_STATUS", false);
          this.$refs["reset-user"].hide();
        });
    },

    registerUser() {
      if (this.form.name.length < 4) {
        this.showToast("Aviso", "warning", "Nome requerido");
        return;
      } else if (this.form.email.length < 4) {
        this.showToast("Aviso", "warning", "E-mail requerido");
        return;
      } else if (this.form.phone.length != 12) {
        this.showToast(
          "Aviso",
          "warning",
          "O número do telemóvel deve conter 12 dígitos."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        this.form.companyId = this.company.id;
        const passingValues = this.form;

        axios
          .post("/api/users", passingValues)
          .then((res) => {
            const { success, message } = res.data;
            if (success === true) {
              console.log(res.data);
              this.showToast("Sucesso!", "success", message);
              this.$store.commit("LOADING_STATUS", false);

              const logsParams = logs(
                this.user,
                `${passingValues.name} cadastrado com sucesso.`,
                "Cadastro de usuário"
              );
              this.sendUserCredentials(logsParams);
              this.refreshUsers();
            } else {
              this.showToast("Erro!", "danger", message);
              this.$store.commit("LOADING_STATUS", false);
              this.refreshUsers();
              this.resetFields();
            }
          })
          .catch((err) => {
            console.log(err);
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
          });
      }
    },

    sendUserCredentials(logsParams) {
      this.$store.commit("LOADING_STATUS", true);
      const passingValues = {
        receipient: this.form.phone,
        accountNumber: this.user.id,
        sender: this.company.smsSender,
        companyId: this.company.id,
        smsBody: `OTP: ${this.form.password} \n${this.company.companyName}`,
      };
      this.$store.dispatch("sendSMSMessage", passingValues);
      this.$store.dispatch("addLog", logsParams);
    },

    updateConfirmation() {
      if (this.form.name.length < 4) {
        this.showToast("Aviso", "warning", "Nome requerido");
        return;
      } else if (this.form.email.length < 4) {
        this.showToast("Aviso", "warning", "E-mail requerido");
        return;
      } else if (this.form.phone.length != 12) {
        this.showToast(
          "Aviso",
          "warning",
          "O número do telemóvel deve conter 12 dígitos."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        const passingValues = this.form;

        axios
          .put(`/api/users/${this.userUpdationId}`, passingValues)
          .then((res) => {
            const { success, message } = res.data;
            if (success === true) {
              console.log(res.data);
              this.showToast("Sucesso!", "success", message);
              this.$store.commit("LOADING_STATUS", false);

              const logsParams = logs(
                this.user,
                `${passingValues.name} actualizado com sucesso.`,
                "Actualização de usuário"
              );
              this.$store.dispatch("addLog", logsParams);

              this.refreshUsers();
              this.resetFields();
            } else {
              this.showToast("Erro!", "danger", message);
              this.$store.commit("LOADING_STATUS", false);
              this.resetFields();
            }
          })
          .catch((err) => {
            console.log(err);
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
          });
      }
    },

    updateUser(user) {
      this.userUpdationId = user.id;
      this.form = {
        name: user.name,
        phone: user.phone,
        email: user.email,
        userRole: user.userRole,
        status: user.status,
        companyId: user.companyId,
      };
    },

    decidedToDelete() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .delete(`/api/users/${this.userDeletionId}`)
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);

            const logsParams = logs(
              this.user,
              `${this.selectedUser.name} com ${this.userDeletionId} excluído com sucesso.`,
              "Exclusão de usuário"
            );
            this.$store.dispatch("addLog", logsParams);

            this.refreshUsers();
          } else {
            this.showToast("Erro!", "warning", data.message);
          }
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.cancelDeletion();
          this.$store.commit("LOADING_STATUS", false);
          this.showToast("Erro!", "danger", err.message);
        });
    },

    deleteUser(user) {
      this.userDeletionId = user.id;
      this.selectedUser = user;
      this.$refs["delete-user"].show();
    },

    cancelDeletion() {
      this.userDeletionId = 0;
      this.$refs["delete-user"].hide();
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    convertRole(role) {
      if (role == 1) {
        return "Admin";
      } else if (role == 2) {
        return "Atendimento";
      } else if (role == 3) {
        return "Analista de crédito";
      }
    },

    convertStatus(status) {
      if (status === 1) {
        return "Activo";
      } else if (status === 0) {
        return "Bloaqueado";
      }
    },

    resetFields() {
      this.userUpdationId = 0;
      this.form = {
        name: "",
        phone: "258",
        email: "",
        password: Math.floor(Math.random() * 1000000) + 1,
        userRole: 2,
        status: 1,
        companyId: 1,
      };
    },
  },
};
</script>
