<template>
  <div>
    <b-overlay :show="isLoading" rounded="sm">
      <b-row>
        <b-col lg="9" md="8" sm="12">
          <b-row>
            <b-col>
              <b-form-group
                label="Nome da empresa"
                class="mt-0"
                label-for="input-1"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-input
                  v-model="form.companyName"
                  size="sm"
                  type="text"
                  placeholder="Nome da empresa"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
            <b-col>
              <b-form-group
                label="E-mail"
                class="mt-0"
                label-for="input-1"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-input
                  v-model="form.companyEmail"
                  size="sm"
                  type="text"
                  placeholder="E-mail"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
          </b-row>
          <b-row>
            <b-col>
              <b-form-group
                label="Telefone"
                class="mt-0"
                label-for="input-1"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-input
                  v-model="form.companyPhone"
                  size="sm"
                  type="number"
                  placeholder="Telefone"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
            <b-col>
              <b-form-group
                label="Gestor da empresa"
                style="font-weight: bold; font-size: 10pt"
                class="mt-0"
                label-for="input-1"
              >
                <b-form-input
                  v-model="form.companyManager"
                  size="sm"
                  type="text"
                  placeholder="Gestor da empresa"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
          </b-row>
          <b-row>
            <b-col>
              <b-form-group
                label="Website institucional"
                class="mt-0"
                label-for="input-1"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-input
                  v-model="form.companyWebsite"
                  size="sm"
                  type="text"
                  placeholder="Website institucional"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
            <b-col>
              <b-form-group
                label="NUIT"
                class="mt-0"
                label-for="input-1"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-input
                  v-model="form.companyNuit"
                  size="sm"
                  type="number"
                  placeholder="NUIT"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
          </b-row>
          <b-row>
            <b-col lg="6">
              <b-form-group
                label="Endereço da empresa"
                label-for="textarea-formatter"
                class="mb-0"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-textarea
                  id="textarea-formatter"
                  v-model="form.companyAddress"
                  placeholder="Enderenço da empresa"
                ></b-form-textarea>
              </b-form-group>
            </b-col>
            <b-col>
              <b-form-group
                label="Juros de mora(%)"
                class="mt-0"
                label-for="input-1"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-input
                  v-model="form.forfeit"
                  size="sm"
                  type="number"
                  step="any"
                  min="1"
                  placeholder="Multa de mora"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
            <b-col>
              <b-form-group
                label="Remetente (SMS)"
                class="mt-0"
                label-for="input-1"
                style="font-weight: bold; font-size: 10pt"
              >
                <b-form-input
                  v-model="form.smsSender"
                  size="sm"
                  type="text"
                  placeholder="Remetente"
                  required
                ></b-form-input>
              </b-form-group>
            </b-col>
            <b-col cols="2">
              <p><br /></p>
              <b-button
                :disabled="isLoading"
                type="submit"
                size="sm"
                block
                variant="success"
                @click="updateCompanyDetails()"
                >Actualizar &nbsp;<b-icon icon="telegram"></b-icon
              ></b-button>
            </b-col>
          </b-row>
        </b-col>
        <b-col class="text-center">
          <h6 class="text-center text-secondary mt-2"><b>LOGO</b></h6>
          <b-progress
            :value="uploadValue"
            :max="100"
            show-progress
            animated
            class="mt-1 mb-1"
            v-if="uploadValue > 0"
          ></b-progress>
          <b-row>
            <b-col class="text-center">
              <b-img
                thumbnail
                fluid
                :src="
                  form.companyLogo != '' ? form.companyLogo : imagePlaceholder
                "
                alt="Company LOGO"
                width="250px"
                heigth="250px"
              ></b-img> </b-col
          ></b-row>
          <b-form-file
            accept="image/*"
            @change="onFileChange"
            class="mt-2 mb-2"
            size="sm"
          ></b-form-file>
          <b-button
            :disabled="isLoading || uploadValue > 0 || !selectedFile"
            type="submit"
            size="sm"
            variant="success"
            @click="onUploadFile()"
            class="mt-2 mb-2"
            >SALVAR <b-icon icon="cloud-upload-fill" font-scale="1"></b-icon
          ></b-button>
        </b-col>
      </b-row>
    </b-overlay>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";
import firebase from "firebase";

import logs from "@/utils/logs";

export default {
  name: "CompanyDetailsComponent",

  data: () => ({
    form: {
      companyName: "",
      companyEmail: "",
      companyWebsite: "",
      companyManager: "",
      smsSender: "",
      companyNuit: "",
      companyPhone: "",
      provinceId: 1,
      districtId: 1,
      companyAddress: "",
      companyLogo: "",
      companyStatus: "",
      forfeit: 1,
    },
    selectedFile: "",
    uploadValue: 0,
    imagePlaceholder:
      "https://firebasestorage.googleapis.com/v0/b/microcredito-79408.appspot.com/o/images%2Flogo.png?alt=media&token=e2582469-6243-41af-9204-40d5d290ad95",
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "token", "company"]),
  },

  created() {
    this.form = this.company;
  },

  methods: {
    updateCompanyDetails() {
      if (
        this.form.companyName.length < 4 ||
        this.form.companyPhone.length != 12 ||
        this.form.companyEmail.length < 10 ||
        this.form.companyManager.length < 4 ||
        this.form.companyWebsite.length < 10 ||
        this.form.companyAddress.length < 5 ||
        this.form.companyNuit.length != 9
      ) {
        this.showToast(
          "Aviso!",
          "warning",
          "Caro usuário, todos campos são de preechimento obrigatório."
        );
        return;
      } else {
        this.$store.commit("LOADING_STATUS", true);
        axios
          .put(`/api/company/${this.company.id}`, this.form)
          .then((res) => {
            const data = res.data;
            if (data.success == true) {
              this.showToast("Sucesso!", "success", data.message);

              const logsParams = logs(
                this.user,
                `Dados da empresa actualizado com sucesso.`,
                "Configurações do sistema"
              );
              this.$store.dispatch("addLog", logsParams);

              this.$store.dispatch("getCompanyDetails", this.company.id);
            } else {
              this.showToast("Erro!", "danger", data.message);
            }
            this.$store.commit("LOADING_STATUS", false);
          })
          .catch((err) => {
            this.showToast("Erro!", "danger", err.message);
            this.$store.commit("LOADING_STATUS", false);
          });
      }
    },

    onFileChange(e) {
      const selectedFile = e.target.files[0]; // accessing file
      this.form.companyLogo = URL.createObjectURL(selectedFile);
      this.selectedFile = selectedFile;
    },

    onUploadFile() {
      if (!this.selectedFile) {
        this.showToast("Erro!", "danger", "Seleccione uma umagem por favor!");
        return;
      }
      const storageRef = firebase
        .storage()
        .ref(`/images/${this.selectedFile.name}`)
        .put(this.selectedFile);
      storageRef.on(
        `state_changed`,
        (snapshot) => {
          this.uploadValue =
            (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
        },
        (err) => {
          this.showToast("Erro!", "danger", err.message);
          console.log(err.message);
        },
        () => {
          this.uploadValue = 0;
          storageRef.snapshot.ref.getDownloadURL().then((url) => {
            this.form.companyLogo = url;
            this.updateCompanyDetails();
          });
        }
      );
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },
  },
};
</script>
